  finalQuestions:[
    {id:"m2-geo-v3-final-01",grade:"middle2",unit:"geometry-properties",conceptId:"isosceles-triangle-angles",level:"concept",type:"multiple-choice",question:"이등변삼각형 ABC에서 AB=AC이고 ∠B=68°입니다. 변 BC를 C쪽으로 연장했을 때 생기는 ∠x(외각)의 크기는 얼마일까요?",choices:["68°","112°","124°","136°"],correctAnswer:"112°",explanation:"AB=AC이므로 ∠C=∠B=68°이고, 외각은 180°-68°=112°입니다.",diagram:'<svg viewBox="-84.6 -24 269.2 198" role="img" aria-label="이등변삼각형 ABC, AB=AC, 밑각 68도, C의 외각 x"><path class="d-shape" d="M0,0 L-60.6,150 L60.6,150 Z"/><text class="d-label" x="0" y="-14" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="-76.6" y="158" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="64.6" y="166" text-anchor="middle" dominant-baseline="central">C</text><line class="d-line d-dash" x1="-60.6" y1="150" x2="160.6" y2="150"/><line class="d-line" x1="-33.5" y1="73.7" x2="-27.1" y2="76.3"/><line class="d-line" x1="27.1" y1="76.3" x2="33.5" y2="73.7"/><path class="d-arc" d="M-49.4,122.2 A30,30 0 0,1 -30.6,150"/><text class="d-label" x="-22.5" y="124.3" text-anchor="middle" dominant-baseline="central">68°</text><path class="d-arc" d="M86.6,150 A26,26 0 0,0 50.9,125.9"/><text class="d-highlight" x="84.1" y="115.2" text-anchor="middle" dominant-baseline="central">x</text></svg>'},
    {id:"m2-geo-v3-final-02",grade:"middle2",unit:"geometry-properties",conceptId:"right-triangle-rhs",level:"concept",type:"multiple-choice",question:"그림의 두 직각삼각형 ABC, DEF에서 ∠B=∠E=90°이고, 빗변 AC=DF, 다른 한 변 BC=EF입니다. 두 삼각형이 합동임을 설명하는 조건은 무엇일까요?",choices:["RHS(빗변과 다른 한 변)","RHA(빗변과 한 예각)","SAS(두 변과 끼인각)","ASA(한 변과 양 끝각)"],correctAnswer:"RHS(빗변과 다른 한 변)",explanation:"빗변과 다른 한 변의 길이가 각각 같으므로 RHS 합동조건입니다.",diagram:'<svg viewBox="-24 -146.9 394 170.9" role="img" aria-label="합동인 두 직각삼각형, 빗변과 다른 한 변이 같음"><path class="d-shape" d="M0,-122.9 L0,0 L86,0 Z"/><path class="d-shape" d="M260,-122.9 L260,0 L346,0 Z"/><path class="d-line" d="M0,-16 L16,-16 L16,0"/><path class="d-line" d="M260,-16 L276,-16 L276,0"/><text class="d-label" x="-12" y="-126.9" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="-12" y="10" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="98" y="10" text-anchor="middle" dominant-baseline="central">C</text><text class="d-label" x="248" y="-126.9" text-anchor="middle" dominant-baseline="central">D</text><text class="d-label" x="248" y="10" text-anchor="middle" dominant-baseline="central">E</text><text class="d-label" x="358" y="10" text-anchor="middle" dominant-baseline="central">F</text><line class="d-line" x1="40.2" y1="-59.4" x2="45.9" y2="-63.4"/><line class="d-line" x1="300.2" y1="-59.4" x2="305.9" y2="-63.4"/><line class="d-line" x1="41" y1="3.5" x2="41" y2="-3.5"/><line class="d-line" x1="45" y1="3.5" x2="45" y2="-3.5"/><line class="d-line" x1="301" y1="3.5" x2="301" y2="-3.5"/><line class="d-line" x1="305" y1="3.5" x2="305" y2="-3.5"/></svg>'},
    {id:"m2-geo-v3-final-03",grade:"middle2",unit:"geometry-properties",conceptId:"triangle-circumcenter",level:"concept",type:"multiple-choice",question:"삼각형 ABC의 외심을 O라고 할 때, OB=9cm입니다. OC의 길이는 얼마일까요?",choices:["4.5cm","9cm","18cm","알 수 없다"],correctAnswer:"9cm",explanation:"외심에서 세 꼭짓점까지의 거리는 모두 같으므로 OC=OB=9cm입니다.",diagram:'<svg viewBox="-154 -164 298 263" role="img" aria-label="삼각형 ABC와 외심 O, OB=9"><path class="d-shape" d="M10,-140 L-130,60 L120,75 Z"/><text class="d-label" x="14" y="-154" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="-146" y="68" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="136" y="83" text-anchor="middle" dominant-baseline="central">C</text><line class="d-line d-dash" x1="-1" y1="1.3" x2="10" y2="-140"/><line class="d-line d-dash" x1="-1" y1="1.3" x2="-130" y2="60"/><line class="d-line d-dash" x1="-1" y1="1.3" x2="120" y2="75"/><circle class="d-point" cx="-1" cy="1.3" r="4"/><text class="d-label" x="13" y="-4.7" text-anchor="middle" dominant-baseline="central">O</text><line class="d-line" x1="8" y1="-69.1" x2="1" y2="-69.6"/><line class="d-line" x1="-67" y1="27.5" x2="-64.1" y2="33.8"/><line class="d-line" x1="57.7" y1="41.1" x2="61.3" y2="35.2"/><text class="d-label" x="-81.5" y="34.6" text-anchor="middle" dominant-baseline="central">9</text><text class="d-highlight" x="73.5" y="44.1" text-anchor="middle" dominant-baseline="central">x</text></svg>'},
    {id:"m2-geo-v3-final-04",grade:"middle2",unit:"geometry-properties",conceptId:"triangle-incenter",level:"concept",type:"multiple-choice",question:"삼각형 ABC의 내심 I에 대해 선분 AI는 ∠A를 이등분합니다. 그림처럼 ∠BAI=32°일 때, ∠IAC(=∠x)의 크기는 얼마일까요?",choices:["16°","32°","58°","64°"],correctAnswer:"32°",explanation:"내심에서 각 꼭짓점으로 그은 선분은 그 꼭짓점의 각을 이등분하므로 ∠IAC=∠BAI=32°입니다.",diagram:'<svg viewBox="-117.7 -24 235.5 198" role="img" aria-label="삼각형 ABC와 내심 I, AI가 각A를 이등분, 절반이 32도"><path class="d-shape" d="M0,0 L-93.7,150 L93.7,150 Z"/><text class="d-label" x="0" y="-14" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="-109.7" y="158" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="109.7" y="158" text-anchor="middle" dominant-baseline="central">C</text><line class="d-line d-dash" x1="0" y1="0" x2="0" y2="98"/><circle class="d-point" cx="0" cy="98" r="4"/><text class="d-label" x="-14" y="94" text-anchor="middle" dominant-baseline="central">I</text><path class="d-arc" d="M-12.7,20.4 A24,24 0 0,0 0,24"/><text class="d-label" x="-10.5" y="36.5" text-anchor="middle" dominant-baseline="central">32°</text><path class="d-arc" d="M0,24 A24,24 0 0,0 12.7,20.4"/><text class="d-highlight" x="10.5" y="36.5" text-anchor="middle" dominant-baseline="central">x</text></svg>'},
    {id:"m2-geo-v3-final-05",grade:"middle2",unit:"geometry-properties",conceptId:"parallelogram-sides-angles",level:"concept",type:"multiple-choice",question:"평행사변형 ABCD에서 ∠A=72°입니다. 이웃한 각의 성질과 대각의 성질을 차례로 이용해서 ∠D(=∠x)의 크기를 구해 보세요.",choices:["72°","108°","118°","144°"],correctAnswer:"108°",explanation:"이웃한 두 각의 합은 180°이므로 ∠B=180°-72°=108°이고, 대각의 크기는 같으므로 ∠D=∠B=108°입니다.",diagram:'<svg viewBox="-24 -147.6 288.2 171.6" role="img" aria-label="평행사변형 ABCD, 각A 72도"><path class="d-shape" d="M0,0 L200,0 L240.2,-123.6 L40.2,-123.6 Z"/><text class="d-label" x="-14" y="6" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="214" y="6" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="254.2" y="-131.6" text-anchor="middle" dominant-baseline="central">C</text><text class="d-label" x="26.2" y="-131.6" text-anchor="middle" dominant-baseline="central">D</text><path class="d-arc" d="M28,0 A28,28 0 0,0 8.7,-26.6"/><text class="d-label" x="35.6" y="-25.9" text-anchor="middle" dominant-baseline="central">72°</text><path class="d-arc" d="M31.5,-97 A28,28 0 0,0 68.2,-123.6"/><text class="d-highlight" x="66" y="-88" text-anchor="middle" dominant-baseline="central">x</text></svg>'},
    {id:"m2-geo-v3-final-06",grade:"middle2",unit:"geometry-properties",conceptId:"rectangle-property",level:"concept",type:"multiple-choice",question:"사각형 ABCD의 네 각이 모두 90°이고, 네 변의 길이가 모두 같습니다. 이 사각형은 어떤 사각형일까요?",choices:["정사각형","직사각형","마름모","평행사변형"],correctAnswer:"정사각형",explanation:"네 각이 모두 직각이면서 네 변의 길이도 모두 같으므로 정사각형입니다.",diagram:'<svg viewBox="-24 -184 208 208" role="img" aria-label="사각형 ABCD, 네 각이 직각, 네 변의 길이가 모두 같음"><path class="d-shape" d="M0,0 L160,0 L160,-160 L0,-160 Z"/><text class="d-label" x="-14" y="8" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="174" y="8" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="174" y="-168" text-anchor="middle" dominant-baseline="central">C</text><text class="d-label" x="-14" y="-168" text-anchor="middle" dominant-baseline="central">D</text><path class="d-line" d="M0,-14 L14,-14 L14,0"/><path class="d-line" d="M146,0 L146,-14 L160,-14"/><path class="d-line" d="M160,-146 L146,-146 L146,-160"/><path class="d-line" d="M14,-160 L14,-146 L0,-146"/><line class="d-line" x1="80" y1="3.5" x2="80" y2="-3.5"/><line class="d-line" x1="163.5" y1="-80" x2="156.5" y2="-80"/><line class="d-line" x1="80" y1="-163.5" x2="80" y2="-156.5"/><line class="d-line" x1="-3.5" y1="-80" x2="3.5" y2="-80"/></svg>'},
    {id:"m2-geo-v3-final-07",grade:"middle2",unit:"geometry-properties",conceptId:"parallelogram-diagonals",level:"concept",type:"multiple-choice",question:"평행사변형 ABCD에서 AB=8cm, BC=5cm입니다. 한 학생이 '평행사변형은 두 대각선이 서로를 이등분하므로, 두 대각선은 항상 수직으로 만난다'고 말했습니다. 이 학생의 설명에서 잘못된 부분은 무엇일까요?",choices:["대각선이 서로를 이등분하는 것과 수직으로 만나는 것은 별개의 성질이다 — 수직은 마름모에서만 항상 성립한다","평행사변형은 대각선이 서로를 이등분하지 않는다","AB와 BC의 길이가 같아야 평행사변형이다","평행사변형에는 대각선을 그을 수 없다"],correctAnswer:"대각선이 서로를 이등분하는 것과 수직으로 만나는 것은 별개의 성질이다 — 수직은 마름모에서만 항상 성립한다",explanation:"평행사변형의 대각선은 서로를 이등분하지만, 일반적으로 수직은 아니에요. 두 대각선이 수직으로 만나는 것은 마름모의 성질입니다.",diagram:'<svg viewBox="-24 -146.2 302.5 170.2" role="img" aria-label="평행사변형 ABCD, 대각선 AC와 BD, AB=8, BC=5"><path class="d-shape" d="M0,0 L210,0 L254.5,-122.2 L44.5,-122.2 Z"/><text class="d-label" x="-14" y="6" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="224" y="6" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="268.5" y="-130.2" text-anchor="middle" dominant-baseline="central">C</text><text class="d-label" x="30.5" y="-130.2" text-anchor="middle" dominant-baseline="central">D</text><line class="d-line" x1="0" y1="0" x2="254.5" y2="-122.2"/><line class="d-line" x1="210" y1="0" x2="44.5" y2="-122.2"/><text class="d-label" x="105" y="18" text-anchor="middle" dominant-baseline="central">8</text><text class="d-label" x="250.2" y="-69.1" text-anchor="middle" dominant-baseline="central">5</text></svg>'},
    {id:"m2-geo-v3-final-08",grade:"middle2",unit:"geometry-properties",conceptId:"quadrilateral-condition-judge",level:"concept",type:"multiple-choice",question:"사각형 ABCD의 두 대각선이 서로 다른 점에서 수직으로 만나고 서로를 이등분합니다. AB=10cm일 때, 나머지 세 변 BC, CD, DA의 길이의 합은 얼마일까요?",choices:["10cm","20cm","30cm","40cm"],correctAnswer:"30cm",explanation:"대각선이 서로 수직이등분하면 이 사각형은 마름모이므로 네 변의 길이가 모두 10cm로 같습니다. 따라서 나머지 세 변의 합은 10×3=30cm입니다.",diagram:'<svg viewBox="-114 -154 228 308" role="img" aria-label="사각형 ABCD, 대각선이 서로 수직이등분, AB=10"><path class="d-shape" d="M0,-130 L90,0 L0,130 L-90,0 Z"/><text class="d-label" x="0" y="-144" text-anchor="middle" dominant-baseline="central">A</text><text class="d-label" x="106" y="4" text-anchor="middle" dominant-baseline="central">B</text><text class="d-label" x="0" y="144" text-anchor="middle" dominant-baseline="central">C</text><text class="d-label" x="-106" y="4" text-anchor="middle" dominant-baseline="central">D</text><line class="d-line d-dash" x1="0" y1="-130" x2="0" y2="130"/><line class="d-line d-dash" x1="90" y1="0" x2="-90" y2="0"/><path class="d-line" d="M0,-12 L12,-12 L12,0"/><line class="d-line" x1="3.5" y1="-65" x2="-3.5" y2="-65"/><line class="d-line" x1="-3.5" y1="65" x2="3.5" y2="65"/><line class="d-line" x1="43" y1="3.5" x2="43" y2="-3.5"/><line class="d-line" x1="47" y1="3.5" x2="47" y2="-3.5"/><line class="d-line" x1="-43" y1="-3.5" x2="-43" y2="3.5"/><line class="d-line" x1="-47" y1="-3.5" x2="-47" y2="3.5"/><text class="d-label" x="65" y="-71" text-anchor="middle" dominant-baseline="central">10</text></svg>'}
  ]
