window.MATH_CONTENT.units["coordinate-geometry"].conceptReviewLearning={estimatedMinutes:"20~25",questions:[
  {stage:"기본문제",conceptId:"distance-between-points",title:"두 점 사이의 거리",question:{id:"h1-coordinate-deep-01",question:"두 점 (1,2), (4,6) 사이의 거리는 얼마인가요?",choices:["4","5","6","7"],correctAnswer:"5",explanation:"√(3²+4²)=5입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-01",question:"두 점 (-1,1), (5,9) 사이의 거리는 얼마인가요?",choices:["8","9","10","12"],correctAnswer:"10",explanation:"√(6²+8²)=10입니다."}},
  {stage:"기본문제",conceptId:"internal-division",title:"중점 좌표",question:{id:"h1-coordinate-deep-02",question:"A(-2,3), B(6,7)의 중점 좌표를 입력하세요.",correctAnswer:"(2,5)",acceptedAnswers:["(2,5)","2,5"],explanation:"((-2+6)/2,(3+7)/2)=(2,5)입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-02",question:"A(1,-3), B(7,5)의 중점 좌표를 입력하세요.",correctAnswer:"(4,1)",acceptedAnswers:["(4,1)","4,1"],explanation:"((1+7)/2,(-3+5)/2)=(4,1)입니다."}},
  {stage:"공식·정의·성질 확인",conceptId:"line-equation",title:"점-기울기 공식",question:{id:"h1-coordinate-deep-03",question:"기울기 m이고 (x₁,y₁)을 지나는 직선: y-y₁=____ 의 빈칸을 완성하세요.",correctAnswer:"m(x-x₁)",acceptedAnswers:["m(x-x₁)","m(x−x₁)","m(x-x1)"],explanation:"점-기울기 꼴은 y-y₁=m(x-x₁)입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-03",question:"기울기 2이고 (a,b)를 지나는 직선: y-b=____ 의 빈칸을 완성하세요.",correctAnswer:"2(x-a)",acceptedAnswers:["2(x-a)","2(x−a)"],explanation:"m=2, (x₁,y₁)=(a,b)를 대입합니다."}},
  {stage:"유형별 문제",conceptId:"internal-division",title:"선분의 내분",question:{id:"h1-coordinate-deep-04",question:"A(0,0), B(9,6)을 AP:PB=1:2로 내분하는 P의 좌표를 입력하세요.",correctAnswer:"(3,2)",acceptedAnswers:["(3,2)","3,2"],explanation:"P는 A에서 B 쪽으로 1/3 지점이므로 (3,2)입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-04",question:"A(0,0), B(12,8)을 AP:PB=1:3으로 내분하는 P의 좌표를 입력하세요.",correctAnswer:"(3,2)",acceptedAnswers:["(3,2)","3,2"],explanation:"A에서 B 쪽으로 1/4 지점입니다."}},
  {stage:"유형별 문제",conceptId:"line-equation",title:"직선의 방정식",question:{id:"h1-coordinate-deep-05",question:"기울기가 -2이고 점 (1,3)을 지나는 직선의 식을 점-기울기 꼴로 입력하세요.",correctAnswer:"y-3=-2(x-1)",acceptedAnswers:["y-3=-2(x-1)","y−3=-2(x−1)"],explanation:"y-3=-2(x-1)입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-05",question:"기울기가 3이고 점 (-1,2)를 지나는 직선의 식을 점-기울기 꼴로 입력하세요.",correctAnswer:"y-2=3(x+1)",acceptedAnswers:["y-2=3(x+1)","y−2=3(x+1)"],explanation:"y-2=3(x-(-1))=3(x+1)입니다."}},
  {stage:"개념 적용문제",conceptId:"line-relations",title:"평행한 직선",question:{id:"h1-coordinate-deep-06",question:"직선 y=3x-4와 평행한 직선의 기울기를 입력하세요.",correctAnswer:"3",acceptedAnswers:["3"],explanation:"평행한 직선의 기울기는 같습니다."},retryQuestion:{id:"h1-coordinate-deep-retry-06",question:"직선 y=-2x+5와 평행한 직선의 기울기를 입력하세요.",correctAnswer:"-2",acceptedAnswers:["-2","−2"],explanation:"같은 기울기 -2를 가집니다."}},
  {stage:"개념 적용문제",conceptId:"line-relations",title:"수직인 직선",question:{id:"h1-coordinate-deep-07",question:"기울기가 2인 직선에 수직인 직선의 기울기를 입력하세요.",correctAnswer:"-1/2",acceptedAnswers:["-1/2","−1/2"],explanation:"두 기울기의 곱이 -1이므로 -1/2입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-07",question:"기울기가 -3인 직선에 수직인 직선의 기울기를 입력하세요.",correctAnswer:"1/3",acceptedAnswers:["1/3"],explanation:"(-3)×(1/3)=-1입니다."}},
  {stage:"마지막 정리문제",conceptId:"line-equation",title:"두 점을 지나는 직선",question:{id:"h1-coordinate-deep-08",question:"두 점 (0,1), (2,5)를 지나는 직선의 방정식을 입력하세요.",correctAnswer:"y=2x+1",acceptedAnswers:["y=2x+1","y = 2x + 1"],explanation:"기울기는 2이고 y절편은 1입니다."},retryQuestion:{id:"h1-coordinate-deep-retry-08",question:"두 점 (0,-2), (3,4)를 지나는 직선의 방정식을 입력하세요.",correctAnswer:"y=2x-2",acceptedAnswers:["y=2x-2","y = 2x - 2","y=2x−2"],explanation:"기울기는 2이고 y절편은 -2입니다."}}
]};

window.MATH_CONTENT.units["linear-equation"].appliedConcepts={estimatedMinutes:"25~30",questions:[
  {stage:"상황 이해",id:"applied-situation-understanding-01",title:"상황에서 모르는 것 찾기",lesson:{summary:"문장제를 풀 때 가장 먼저 할 일은, 이 상황에서 우리가 아직 모르는 값(구해야 하는 값)이 무엇인지 찾는 거예요.",keyPoint:"모르는 값을 먼저 찾자",example:"\"어떤 수에 5를 더하면 12\" → 모르는 것은 \"어떤 수\""},question:{type:"multiple-choice",question:"어떤 수에 5를 더했더니 12가 되었습니다. 이 상황에서 우리가 아직 모르는 것은 무엇인가요?",choices:["어떤 수","5","12","더하기"],correctAnswer:"어떤 수",explanation:"문제에서 \"어떤 수\"라고만 하고 정확한 값을 알려주지 않았으므로, 그 값이 우리가 모르는 것이에요.",id:"m1-linear-applied-sit-01",grade:"middle1",unit:"linear-equation",conceptId:"situation-understanding"},retryQuestion:{type:"multiple-choice",question:"사탕을 몇 개 가지고 있었는데 3개를 더 받아 8개가 되었습니다. 이 상황에서 우리가 구해야 하는 값은 무엇인가요?",choices:["처음 가지고 있던 사탕 수","받은 사탕 수","전체 사탕 수","3"],correctAnswer:"처음 가지고 있던 사탕 수",explanation:"\"몇 개 가지고 있었는데\"라고만 하고 알려주지 않은 처음 사탕 수가 우리가 구해야 하는 값이에요.",id:"m1-linear-applied-retry-sit-01",grade:"middle1",unit:"linear-equation",conceptId:"situation-understanding"}},
  {stage:"상황 이해",id:"applied-situation-understanding-02",title:"상황에서 모르는 것 찾기 2",lesson:{summary:"숫자가 여러 개 나와도, 그중 \"정확히 알려주지 않은\" 값 하나만 모르는 값이에요.",keyPoint:"문장에서 물음표처럼 비어있는 값을 찾자",example:"\"구슬을 x개 가지고 있었는데 5개를 잃어버려서 11개가 되었다\" → 모르는 것은 \"처음 구슬 수\""},question:{type:"multiple-choice",question:"어떤 수에서 7을 뺐더니 9가 되었습니다. 이 상황에서 우리가 아직 모르는 것은 무엇인가요?",choices:["어떤 수","7","9","빼기"],correctAnswer:"어떤 수",explanation:"\"어떤 수\"의 정확한 값을 모르므로 그것이 우리가 구해야 하는 값이에요.",id:"m1-linear-applied-sit-02",grade:"middle1",unit:"linear-equation",conceptId:"situation-understanding"},retryQuestion:{type:"multiple-choice",question:"구슬을 몇 개 가지고 있었는데 5개를 잃어버려서 11개가 되었습니다. 이 상황에서 우리가 구해야 하는 값은 무엇인가요?",choices:["처음 가지고 있던 구슬 수","잃어버린 구슬 수","남은 구슬 수","5"],correctAnswer:"처음 가지고 있던 구슬 수",explanation:"처음 구슬 수를 알려주지 않았으므로 그것이 우리가 구해야 하는 값이에요.",id:"m1-linear-applied-retry-sit-02",grade:"middle1",unit:"linear-equation",conceptId:"situation-understanding"}},
  {stage:"x로 정하기",id:"applied-define-x-03",title:"무엇을 x로 놓을지 정하기",lesson:{summary:"모르는 값을 찾았다면, 그 값을 알파벳 x로 표시해요. 이렇게 하면 식을 세우기 쉬워져요.",keyPoint:"모르는 값 = x",example:"\"어떤 수의 3배가 18\" → 어떤 수를 x로 놓는다"},question:{type:"multiple-choice",question:"어떤 수의 3배가 18입니다. 이때 x로 놓아야 할 것은 무엇인가요?",choices:["어떤 수","3","18","3배"],correctAnswer:"어떤 수",explanation:"우리가 모르는 값인 \"어떤 수\"를 x로 놓아요.",id:"m1-linear-applied-x-03",grade:"middle1",unit:"linear-equation",conceptId:"define-x"},retryQuestion:{type:"multiple-choice",question:"어떤 수의 4배가 24입니다. 이때 x로 놓아야 할 것은 무엇인가요?",choices:["어떤 수","4","24","4배"],correctAnswer:"어떤 수",explanation:"모르는 값인 \"어떤 수\"를 x로 놓아요.",id:"m1-linear-applied-retry-x-03",grade:"middle1",unit:"linear-equation",conceptId:"define-x"}},
  {stage:"x로 정하기",id:"applied-define-x-04",title:"무엇을 x로 놓을지 정하기 2",lesson:{summary:"문장이 조금 길어져도, 여전히 \"정확한 값을 알려주지 않은 것\" 하나를 찾아 x로 놓으면 돼요.",keyPoint:"긴 문장에서도 모르는 값 하나만 x",example:"\"문제집의 문제 수의 2배에서 4를 빼면 10\" → 문제집의 문제 수를 x로 놓는다"},question:{type:"multiple-choice",question:"어느 문제집의 문제 수의 2배에서 4를 뺐더니 10이 되었습니다. 이때 x로 놓아야 할 것은 무엇인가요?",choices:["문제집의 문제 수","2배","4","10"],correctAnswer:"문제집의 문제 수",explanation:"모르는 값인 \"문제집의 문제 수\"를 x로 놓아요.",id:"m1-linear-applied-x-04",grade:"middle1",unit:"linear-equation",conceptId:"define-x"},retryQuestion:{type:"multiple-choice",question:"어느 동아리의 회원 수의 3배에서 2를 뺐더니 13이 되었습니다. 이때 x로 놓아야 할 것은 무엇인가요?",choices:["동아리 회원 수","3배","2","13"],correctAnswer:"동아리 회원 수",explanation:"모르는 값인 \"동아리 회원 수\"를 x로 놓아요.",id:"m1-linear-applied-retry-x-04",grade:"middle1",unit:"linear-equation",conceptId:"define-x"}},
  {stage:"식으로 바꾸기",id:"applied-sentence-to-equation-05",title:"짧은 문장을 식으로 바꾸기",lesson:{summary:"x를 정했다면, 문장을 그대로 수식 기호(+, -, ×, =)로 바꿔 써 봐요.",keyPoint:"\"더하면\"=+, \"배\"=×, \"이 된다/이다\"== ",example:"\"어떤 수 x에 5를 더하면 12\" → x + 5 = 12"},question:{type:"fill-blank",question:"어떤 수 x에 5를 더하면 12입니다. 이를 식으로 나타내면?",correctAnswer:"x+5=12",acceptedAnswers:["x+5=12","5+x=12"],explanation:"\"5를 더하면\"은 +5, \"12가 된다\"는 =12로 바꿔 쓰면 x+5=12예요.",id:"m1-linear-applied-eq-05",grade:"middle1",unit:"linear-equation",conceptId:"sentence-to-equation"},retryQuestion:{type:"fill-blank",question:"어떤 수 x에서 3을 빼면 9입니다. 이를 식으로 나타내면?",correctAnswer:"x-3=9",acceptedAnswers:["x-3=9"],explanation:"\"3을 빼면\"은 -3, \"9가 된다\"는 =9로 바꿔 쓰면 x-3=9예요.",id:"m1-linear-applied-retry-eq-05",grade:"middle1",unit:"linear-equation",conceptId:"sentence-to-equation"}},
  {stage:"식으로 바꾸기",id:"applied-sentence-to-equation-06",title:"짧은 문장을 식으로 바꾸기 2",lesson:{summary:"\"~의 배\"는 곱셈으로 바꿔요. \"3배\"는 3×x, 즉 3x로 써요.",keyPoint:"\"~의 O배\"=Ox",example:"\"어떤 수 x의 3배는 18\" → 3x = 18"},question:{type:"fill-blank",question:"어떤 수 x의 3배는 18입니다. 이를 식으로 나타내면?",correctAnswer:"3x=18",acceptedAnswers:["3x=18"],explanation:"\"3배\"는 3×x, 즉 3x로 쓰므로 3x=18이에요.",id:"m1-linear-applied-eq-06",grade:"middle1",unit:"linear-equation",conceptId:"sentence-to-equation"},retryQuestion:{type:"fill-blank",question:"어떤 수 x의 4배는 24입니다. 이를 식으로 나타내면?",correctAnswer:"4x=24",acceptedAnswers:["4x=24"],explanation:"\"4배\"는 4x로 쓰므로 4x=24예요.",id:"m1-linear-applied-retry-eq-06",grade:"middle1",unit:"linear-equation",conceptId:"sentence-to-equation"}},
  {stage:"식으로 바꾸기",id:"applied-sentence-to-equation-07",title:"짧은 문장을 식으로 바꾸기 3",lesson:{summary:"배와 뺄셈이 함께 있으면, 먼저 배(곱셈) 부분을 쓰고 그다음 빼는 수를 이어서 써요.",keyPoint:"O배 먼저, 그다음 빼기/더하기",example:"\"어떤 수 x의 2배에서 4를 빼면 10\" → 2x - 4 = 10"},question:{type:"fill-blank",question:"어떤 수 x의 2배에서 4를 빼면 10입니다. 이를 식으로 나타내면?",correctAnswer:"2x-4=10",acceptedAnswers:["2x-4=10"],explanation:"\"2배\"는 2x, 거기서 \"4를 빼면\"은 -4이므로 2x-4=10이에요.",id:"m1-linear-applied-eq-07",grade:"middle1",unit:"linear-equation",conceptId:"sentence-to-equation"},retryQuestion:{type:"fill-blank",question:"어떤 수 x의 3배에서 2를 빼면 13입니다. 이를 식으로 나타내면?",correctAnswer:"3x-2=13",acceptedAnswers:["3x-2=13"],explanation:"\"3배\"는 3x, 거기서 \"2를 빼면\"은 -2이므로 3x-2=13이에요.",id:"m1-linear-applied-retry-eq-07",grade:"middle1",unit:"linear-equation",conceptId:"sentence-to-equation"}},
  {stage:"식 세우기",id:"applied-set-up-equation-09",title:"물건 가격으로 식 세우기",lesson:{summary:"가격 문제는 \"낸 돈 = 물건값 + 거스름돈\"처럼 상황을 그대로 식으로 옮기면 돼요.",keyPoint:"낸 돈, 물건값, 거스름돈의 관계를 그대로 식으로",example:"지우개 1개 x원, 4개 사고 2000원 내고 800원 거슬러 받음 → 4x+800=2000"},question:{id:"m1-linear-applied-set-09",grade:"middle1",unit:"linear-equation",conceptId:"set-up-equation",type:"multiple-choice",question:"지우개 한 개의 가격을 x원이라고 할 때, 지우개 4개를 사고 2000원을 냈더니 800원을 거슬러 받았습니다. 이 상황을 나타낸 옳은 식은 무엇인가요?",choices:["4x+800=2000","4x-800=2000","4x=2000-800×2","800-4x=2000"],correctAnswer:"4x+800=2000",explanation:"지우개 4개 값(4x)에 거스름돈(800)을 더하면 낸 돈(2000)과 같아요."},retryQuestion:{id:"m1-linear-applied-retry-set-09",grade:"middle1",unit:"linear-equation",conceptId:"set-up-equation",type:"multiple-choice",question:"공책 한 권의 가격을 x원이라고 할 때, 공책 3권을 사고 5000원을 냈더니 1100원을 거슬러 받았습니다. 이 상황을 나타낸 옳은 식은 무엇인가요?",choices:["3x+1100=5000","3x-1100=5000","3x=1100","5000+1100=3x"],correctAnswer:"3x+1100=5000",explanation:"공책 3권 값(3x)에 거스름돈(1100)을 더하면 낸 돈(5000)과 같아요."}},
  {stage:"식 세우기",id:"applied-set-up-equation-11",title:"용돈으로 잘못 세운 식 찾기",lesson:{summary:"식을 세울 때는 \"쓴 돈은 빼는 것\"처럼 상황의 방향(더하기/빼기)을 정확히 맞춰야 해요.",keyPoint:"쓴 만큼은 빼고, 받은 만큼은 더한다",example:"용돈 x원에서 3000원 쓰고 5000원 남음 → x-3000=5000 (O), x+3000=5000 (X)"},question:{id:"m1-linear-applied-set-11",grade:"middle1",unit:"linear-equation",conceptId:"set-up-equation",type:"multiple-choice",question:"용돈을 x원 받았는데, 그중 3000원을 쓰고 5000원이 남았습니다. 한 학생이 이 상황을 \"x+3000=5000\"이라는 식으로 세웠어요. 무엇이 잘못되었나요?",choices:["쓴 돈은 더한 게 아니라 빼야 한다(x-3000=5000이어야 한다)","5000과 3000의 위치가 바뀌어야 한다","x가 아니라 3000을 미지수로 놓아야 한다","이 식은 맞는 식이다"],correctAnswer:"쓴 돈은 더한 게 아니라 빼야 한다(x-3000=5000이어야 한다)",explanation:"받은 용돈에서 쓴 돈을 \"뺀\" 것이 남은 돈이므로 x-3000=5000이 맞아요."},retryQuestion:{id:"m1-linear-applied-retry-set-11",grade:"middle1",unit:"linear-equation",conceptId:"set-up-equation",type:"multiple-choice",question:"학생 수를 x명이라 하면, 학생 수의 2배에서 6을 뺀 값이 20입니다. 한 학생이 이를 \"2x+6=20\"이라는 식으로 세웠어요. 무엇이 잘못되었나요?",choices:["뺀 것을 더한 식으로 잘못 세웠다(2x-6=20이어야 한다)","2와 6의 위치가 바뀌어야 한다","x 대신 20을 미지수로 놓아야 한다","이 식은 맞는 식이다"],correctAnswer:"뺀 것을 더한 식으로 잘못 세웠다(2x-6=20이어야 한다)",explanation:"\"뺀 값\"이라고 했으므로 -6이 맞고, 2x-6=20이어야 해요."}},
  {stage:"방정식 풀기",id:"applied-solve-equation-12",title:"짧은 방정식 계산",lesson:{summary:"등식의 성질을 이용해 x만 남을 때까지 양변을 정리하면 답을 구할 수 있어요.",keyPoint:"양변을 같은 수로 나누거나 곱해서 x만 남기기",example:"3x=18 → 양변을 3으로 나누면 x=6"},question:{type:"fill-blank",question:"3x = 18을 풀면 x는 얼마인가요?",correctAnswer:"6",acceptedAnswers:["6"],explanation:"양변을 3으로 나누면 x=6이에요.",id:"m1-linear-applied-solve-12",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation"},retryQuestion:{type:"fill-blank",question:"4x = 24를 풀면 x는 얼마인가요?",correctAnswer:"6",acceptedAnswers:["6"],explanation:"양변을 4로 나누면 x=6이에요.",id:"m1-linear-applied-retry-solve-12",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation"}},
  {stage:"방정식 풀기",id:"applied-solve-equation-14",title:"학생 수 문장제 풀기",lesson:{summary:"문장제도 식을 세운 뒤에는 똑같이 방정식을 풀어 x를 구하면 돼요.",keyPoint:"식을 세운 뒤 등식의 성질로 x 구하기",example:"학생 수 x명의 2배에서 5를 빼면 41 → 2x-5=41 → x=23"},question:{id:"m1-linear-applied-solve-14",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation",type:"fill-blank",question:"어느 반 학생 수의 2배에서 5를 빼면 41입니다. 이 반 학생 수를 구하세요.",correctAnswer:"23",acceptedAnswers:["23"],explanation:"2x-5=41이므로 2x=46, x=23이에요."},retryQuestion:{id:"m1-linear-applied-retry-solve-14",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation",type:"fill-blank",question:"어느 동아리 회원 수의 3배에서 2를 빼면 13입니다. 이 동아리 회원 수를 구하세요.",correctAnswer:"5",acceptedAnswers:["5"],explanation:"3x-2=13이므로 3x=15, x=5예요."}},
  {stage:"방정식 풀기",id:"applied-solve-equation-16",title:"두 조건이 있는 나이 문장제",lesson:{summary:"조건이 두 개 있을 때는, 먼저 알고 있는 조건으로 필요한 값을 구한 뒤 나머지 조건에 적용해요.",keyPoint:"조건을 순서대로 하나씩 적용하기",example:"3년 후 아버지 나이 44살, 그때 민수 나이는 아버지 나이의 절반 → 44÷2=22"},question:{id:"m1-linear-applied-solve-16",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation",type:"fill-blank",question:"3년 후 아버지 나이가 44살이고, 그때 민수의 나이는 아버지 나이의 절반이라고 합니다. 3년 후 민수의 나이를 구하세요.",correctAnswer:"22",acceptedAnswers:["22"],explanation:"3년 후 민수의 나이를 x라 하면 x=44÷2=22예요."},retryQuestion:{id:"m1-linear-applied-retry-solve-16",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation",type:"fill-blank",question:"3년 후 어머니 나이가 42살이고, 그때 지수의 나이는 어머니 나이의 3분의 1이라고 합니다. 3년 후 지수의 나이를 구하세요.",correctAnswer:"14",acceptedAnswers:["14"],explanation:"3년 후 지수의 나이를 x라 하면 x=42÷3=14예요."}},
  {stage:"방정식 풀기",id:"applied-solve-equation-18",title:"도형의 둘레로 방정식 풀기",lesson:{summary:"직사각형의 둘레는 (가로+세로)×2예요. 이 관계를 그대로 방정식으로 세워 풀면 돼요.",keyPoint:"둘레 = (가로+세로)×2",example:"가로 x, 세로 6, 둘레 28 → 2(x+6)=28 → x=8"},question:{id:"m1-linear-applied-solve-18",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation",type:"fill-blank",question:"가로가 x cm, 세로가 6cm인 직사각형의 둘레가 28cm입니다. 가로의 길이를 구하세요.",correctAnswer:"8",acceptedAnswers:["8"],explanation:"2(x+6)=28이므로 x+6=14, x=8이에요."},retryQuestion:{id:"m1-linear-applied-retry-solve-18",grade:"middle1",unit:"linear-equation",conceptId:"solve-equation",type:"fill-blank",question:"가로가 x cm, 세로가 5cm인 직사각형의 둘레가 26cm입니다. 가로의 길이를 구하세요.",correctAnswer:"8",acceptedAnswers:["8"],explanation:"2(x+5)=26이므로 x+5=13, x=8이에요."}},
  {stage:"검산",id:"applied-verify-answer-19",title:"답을 원래 식에 대입해 확인하기",lesson:{summary:"답을 구했다면 꼭 원래 식(또는 문장)에 다시 넣어서 맞는지 확인하는 습관을 들여요.",keyPoint:"구한 답을 원래 식에 대입해 참인지 확인",example:"3x=18에서 x=6 → 3×6=18 (참)"},question:{type:"multiple-choice",question:"어떤 수 x에 대해 3x=18을 풀어 x=6을 구했습니다. 이 답이 맞는지 확인하는 방법은?",choices:["x=6을 원래 식에 다시 대입해 3×6=18인지 확인한다","답을 2배로 늘려본다","처음 문장을 다시 읽지 않아도 된다","단위를 무시하고 숫자만 본다"],correctAnswer:"x=6을 원래 식에 다시 대입해 3×6=18인지 확인한다",explanation:"구한 답을 원래 식에 넣어 등식이 참이 되는지 확인하면 돼요.",id:"m1-linear-applied-check-19",grade:"middle1",unit:"linear-equation",conceptId:"verify-answer"},retryQuestion:{type:"multiple-choice",question:"어떤 수 x에 대해 x-3=9를 풀어 x=12를 구했습니다. 이 답이 맞는지 확인하는 방법은?",choices:["x=12를 원래 식에 다시 대입해 12-3=9인지 확인한다","답에 3을 더 뺀다","처음 문장을 다시 읽지 않아도 된다","단위를 무시하고 숫자만 본다"],correctAnswer:"x=12를 원래 식에 다시 대입해 12-3=9인지 확인한다",explanation:"구한 답을 원래 식에 넣어 등식이 참이 되는지 확인하면 돼요.",id:"m1-linear-applied-retry-check-19",grade:"middle1",unit:"linear-equation",conceptId:"verify-answer"}},
  {stage:"검산",id:"applied-verify-answer-21",title:"종합 문장제로 마무리",lesson:{summary:"마지막으로, 배운 것을 모두 활용해 상황→식→풀이→확인까지 스스로 해봐요.",keyPoint:"상황 이해 → x 정하기 → 식 세우기 → 풀기 → 확인",example:"사탕 x개를 5명에게 나누어 1명당 7개 → x÷5=7 → x=35"},question:{id:"m1-linear-applied-check-21",grade:"middle1",unit:"linear-equation",conceptId:"verify-answer",type:"fill-blank",question:"사탕 x개를 학생 5명에게 똑같이 나누어 주었더니 한 명당 7개씩 받았습니다. 처음 사탕은 몇 개였나요?",correctAnswer:"35",acceptedAnswers:["35"],explanation:"x÷5=7이므로 x=35예요. 35÷5=7로 확인해보면 맞아요."},retryQuestion:{id:"m1-linear-applied-retry-check-21",grade:"middle1",unit:"linear-equation",conceptId:"verify-answer",type:"fill-blank",question:"구슬 x개를 학생 4명에게 똑같이 나누어 주었더니 한 명당 9개씩 받았습니다. 처음 구슬은 몇 개였나요?",correctAnswer:"36",acceptedAnswers:["36"],explanation:"x÷4=9이므로 x=36이에요. 36÷4=9로 확인해보면 맞아요."}}
]};
